452	    public virtual async Task<int> GetPipelineId(string org, string teamProject, string pipeline)
453	    {
454	        org = org ?? throw new ArgumentNullException(nameof(org));
455	        teamProject = teamProject ?? throw new ArgumentNullException(nameof(teamProject));
456	        pipeline = pipeline ?? throw new ArgumentNullException(nameof(pipeline));
457	
458	        var pipelinePath = NormalizePipelinePath(pipeline);
459	
460	        if (_pipelineIds.TryGetValue((org.ToUpper(), teamProject.ToUpper(), pipelinePath.ToUpper()), out var result))
461	        {
462	            return result;
463	        }
464	
465	        var url = $"{_adoBaseUrl}/{org.EscapeDataString()}/{teamProject.EscapeDataString()}/_apis/build/definitions?queryOrder=definitionNameAscending";
466	        var response = await _client.GetWithPagingAsync(url);
467	
468	        foreach (var item in response)
469	        {
470	            var path = NormalizePipelinePath((string)item["path"], (string)item["name"]);
471	            var id = (int)item["id"];
472	
473	            var success = _pipelineIds.TryAdd((org.ToUpper(), teamProject.ToUpper(), path.ToUpper()), id);
474	
475	            if (!success)
476	            {
477	                _log.LogWarning($"Multiple pipelines with the same path/name were found [org: {org} project: {teamProject} pipeline: {path}]. Ignoring pipeline ID {id}");
478	            }
479	        }
480	
481	        return _pipelineIds.TryGetValue((org.ToUpper(), teamProject.ToUpper(), pipelinePath.ToUpper()), out result)
482	            ? result
483	            : response.Count(x => ((string)x["name"]).ToUpper() == pipeline.ToUpper()) == 1
484	            ? (int)response.Single(x => ((string)x["name"]).ToUpper() == pipeline.ToUpper())["id"]
485	            : throw new ArgumentException("Unable to find the specified pipeline", nameof(pipeline));
486	    }
