using System.Threading.Tasks;
using Newtonsoft.Json.Linq;
using OctoshiftCLI.Extensions;
using OctoshiftCLI.Models;

namespace OctoshiftCLI.Services;

/// <summary>
/// Orchestrates a safe, end-to-end test of an Azure DevOps to GitHub pipeline migration.
/// The pipeline is temporarily rewired to GitHub, a build is queued, and the pipeline is
/// then restored back to its original Azure DevOps repository regardless of the outcome.
/// </summary>
public class PipelineTestService
{
    private const int DefaultMonitorTimeoutMinutes = 30;
    private const int PollIntervalSeconds = 10;

    private readonly OctoLogger _log;
    private readonly AdoApi _adoApi;
    private readonly AdoPipelineTriggerService _pipelineTriggerService;

    public PipelineTestService(OctoLogger log, AdoApi adoApi, AdoPipelineTriggerService pipelineTriggerService)
    {
        _log = log;
        _adoApi = adoApi;
        _pipelineTriggerService = pipelineTriggerService;
    }

    public virtual async Task<PipelineTestResult> TestPipeline(PipelineTestArgs args)
    {
        if (args is null)
        {
            throw new ArgumentNullException(nameof(args));
        }

        var result = new PipelineTestResult
        {
            AdoOrg = args.AdoOrg,
            AdoTeamProject = args.AdoTeamProject,
            PipelineName = args.PipelineName,
            PipelineId = args.PipelineId,
            StartTime = DateTime.UtcNow
        };

        // Resolve the pipeline id from its name if one wasn't supplied.
        if (result.PipelineId <= 0)
        {
            result.PipelineId = await _adoApi.GetPipelineId(args.AdoOrg, args.AdoTeamProject, args.PipelineName);
        }

        // Capture the original pipeline definition so we can restore it later.
        var definitionUrl = $"/{args.AdoOrg.EscapeDataString()}/{args.AdoTeamProject.EscapeDataString()}/_apis/build/definitions/{result.PipelineId}?api-version=6.0";
        var originalDefinition = JObject.Parse(await _adoApi.GetAsync(definitionUrl));

        result.AdoRepoName = (string)originalDefinition["repository"]?["name"];

        var (defaultBranch, clean, checkoutSubmodules, triggers) = await _adoApi.GetPipeline(args.AdoOrg, args.AdoTeamProject, result.PipelineId);

        // Rewire the pipeline to GitHub.
        await _pipelineTriggerService.RewirePipelineToGitHub(
            args.AdoOrg,
            args.AdoTeamProject,
            result.PipelineId,
            defaultBranch,
            clean,
            checkoutSubmodules,
            args.GithubOrg,
            args.GithubRepo,
            args.ServiceConnectionId,
            triggers,
            args.TargetApiUrl);

        result.RewiredSuccessfully = true;
        _log.LogInformation($"Successfully rewired pipeline {result.PipelineName} to GitHub for testing");

        if (args.DryRun)
        {
            _log.LogInformation("Dry run requested - skipping build queue.");
        }
        else
        {
            var (buildId, buildUrl) = await _adoApi.QueueBuild(args.AdoOrg, args.AdoTeamProject, result.PipelineId, $"refs/heads/{defaultBranch}");
            result.BuildId = buildId;
            result.BuildUrl = buildUrl;
        }

        // Always attempt to restore the pipeline back to its original ADO repository.
        try
        {
            await _pipelineTriggerService.RestorePipelineToAdoRepo(originalDefinition, args.AdoOrg, args.AdoTeamProject, result.PipelineId);
            result.RestoredSuccessfully = true;
            _log.LogInformation($"Successfully restored pipeline {result.PipelineName} to its original Azure DevOps repository");
        }
        catch (Exception ex)
        {
            result.RestoredSuccessfully = false;
            result.ErrorMessage = "Failed to restore: " + ex.Message;
            _log.LogError($"Failed to restore pipeline {result.PipelineName}: {ex.Message}");
            return result;
        }

        // Monitor the queued build and capture its final status.
        if (result.BuildId.HasValue)
        {
            await MonitorBuild(args, result);
        }

        result.EndTime = DateTime.UtcNow;

        return result;
    }

    private async Task MonitorBuild(PipelineTestArgs args, PipelineTestResult result)
    {
        var timeoutMinutes = args.MonitorTimeoutMinutes > 0 ? args.MonitorTimeoutMinutes : DefaultMonitorTimeoutMinutes;
        var deadline = DateTime.UtcNow.AddMinutes(timeoutMinutes);

        while (true)
        {
            var (status, buildResult, buildUrl) = await _adoApi.GetBuildStatus(args.AdoOrg, args.AdoTeamProject, result.BuildId.Value);

            result.Status = status;
            result.Result = buildResult;

            if (buildUrl.HasValue())
            {
                result.BuildUrl = buildUrl;
            }

            if (!result.IsRunning || result.IsCompleted)
            {
                break;
            }

            if (DateTime.UtcNow >= deadline)
            {
                _log.LogWarning($"Timed out after {timeoutMinutes} minutes while monitoring build {result.BuildId}");
                break;
            }

            await Task.Delay(TimeSpan.FromSeconds(PollIntervalSeconds));
        }
    }
}
